149	#[cfg(test)]
150	mod tests {
151	    use pegainfer_core::tensor::HiddenStates;
152	    use pegainfer_kv_cache::KvCacheManager;
153	
154	    use super::*;
155	    use crate::prefix_cache::Qwen35PrefixCache;
156	
157	    fn greedy_sample_batch(model: &Qwen35Model, logits: &HiddenStates, rows: usize) -> Vec<u32> {
158	        let params = vec![pegainfer_frontend::sampler::SamplingParams::default(); rows];
159	        let params_refs: Vec<&pegainfer_frontend::sampler::SamplingParams> =
160	            params.iter().collect();
161	        let mut scratch = pegainfer_sample::SampleScratch::with_selection_width(
162	            &model.ctx,
163	            model.config.selection_vocab,
164	            model.config.decodable_vocab,
165	            rows,
166	        )
167	        .unwrap();
168	        let steps = vec![0u64; params_refs.len()];
169	        pegainfer_sample::select_batch(&model.ctx, logits, &params_refs, &steps, 0, &mut scratch)
170	            .unwrap()
171	    }
172	
173	    /// The alignment pad columns must come out of the model already masked, on
174	    /// both the prefill and the decode logits path. A logits site that ran the
175	    /// output projection without the mask leaves them selectable, and nothing
176	    /// else in the suite would notice: the pad rows are trained embeddings with
177	    /// plausible logits, so the failure shows up as an undecodable id on the
178	    /// wire rather than a crash.
179	    #[test]
180	    fn pad_columns_are_suppressed_on_the_model_logits_paths() {
181	        let Some(model_path) = crate::test_fixture::model_path_or_skip(
182	            "pad_columns_are_suppressed_on_the_model_logits_paths",
183	        ) else {
184	            return;
185	        };
186	        let model = Qwen35Model::from_safetensors(&model_path, 0, 2, 0).unwrap();
187	
188	        let decodable = model.config.decodable_vocab;
189	        let selection = model.config.selection_vocab;
190	        if decodable == selection {
191	            eprintln!("checkpoint needs no alignment pad; nothing to assert");
192	            return;
193	        }
194	
195	        let pad_tail_is_suppressed = |logits: &HiddenStates, label: &str| {
196	            assert_eq!(logits.hidden_dim, selection, "{label}: arena width");
197	            let row = crate::ops::extract_vec(&model.ctx, logits, 0).unwrap();
198	            let row = row.to_host(&model.ctx).unwrap();
199	            for (id, value) in row.iter().enumerate().take(selection).skip(decodable) {
200	                assert!(
201	                    value.is_sign_negative() && value.is_infinite(),
202	                    "{label}: pad id {id} survived selection (want -inf, got {value})"
203	                );
204	            }
205	            assert!(
206	                row[..decodable].iter().any(|value| value.is_finite()),
207	                "{label}: decodable vocab came out entirely -inf"
208	            );
209	        };
210	
211	        let prompt = vec![9707, 374, 220, 17];
212	        let prompt_refs = [&prompt[..]];
213	        let manager =
214	            KvCacheManager::from_buffer(model.kv_buffer().clone(), model.kv_buffer().num_blocks())
215	                .unwrap();
216	        let cache = Qwen35PrefixCache::new(manager, 0).unwrap();
217	        let mut kv = cache.pool().new_request(prompt.clone(), 2, None);
218	        cache.schedule_prefill(&mut kv, prompt.len()).unwrap();
219	        let views = [cache.prefill_view(&kv, prompt.len())];
220	        let mut rec_states =
221	            [RecurrentState::new(&model.ctx, &model.config, model.geometry).unwrap()];
222	        let mut rec_refs: Vec<&mut RecurrentState> = rec_states.iter_mut().collect();
223	        let prefill_logits = model
224	            .batch_prefill_logits(&prompt_refs, &views, &mut rec_refs, cache.buffer())
225	            .unwrap();
226	        pad_tail_is_suppressed(&prefill_logits, "prefill");
227	
228	        let next = greedy_sample_batch(&model, &prefill_logits, 1)[0];
229	        cache.apply_prefill(&mut kv, Some(next)).unwrap();
230	        let mut graph_state = model
231	            .create_batch_decode_graph_state(cache.pool().padding_block_id())
232	            .unwrap();
233	        graph_state
234	            .copy_state_to_slot(&model.ctx, &rec_states[0], 0)
235	            .unwrap();
236	        cache.schedule_decode(&mut kv).unwrap();
237	        let decode_views = [cache.decode_view(&kv)];
238	        model
239	            .batch_decode_graph(
240	                &[next],
241	                &decode_views,
242	                cache.buffer(),
243	                &mut graph_state,
244	                DecodeGraphUse::Serve,
245	            )
246	            .unwrap();
247	        pad_tail_is_suppressed(&graph_state.buffers.logits, "decode");
248	        let decoded = greedy_sample_batch(&model, &graph_state.buffers.logits, 1)[0];
249	        cache.apply_decode(&mut kv, decoded).unwrap();
250	    }
251	
252	    fn run_decode_path(model: &Qwen35Model, unified: bool) -> (Vec<u32>, Vec<u32>) {
253	        let prompt_a: Vec<u32> = vec![9707];
254	        let prompt_b: Vec<u32> = vec![3838, 374, 220, 17, 10, 17];
255	        let prompts = [&prompt_a[..], &prompt_b[..]];
256	        let num_steps = 5;
257	        let manager =
258	            KvCacheManager::from_buffer(model.kv_buffer().clone(), model.kv_buffer().num_blocks())
259	                .unwrap();
260	        let cache = Qwen35PrefixCache::new(manager, 0).unwrap();
261	        let mut kvs = vec![
262	            cache.pool().new_request(prompt_a.clone(), num_steps, None),
263	            cache.pool().new_request(prompt_b.clone(), num_steps, None),
264	        ];
265	        for (kv, prompt) in kvs.iter_mut().zip(prompts) {
266	            cache.schedule_prefill(kv, prompt.len()).unwrap();
267	        }
268	        let views = kvs
269	            .iter()
270	            .zip(prompts)
271	            .map(|(kv, prompt)| cache.prefill_view(kv, prompt.len()))
272	            .collect::<Vec<_>>();
273	        let mut rec_states = [
274	            RecurrentState::new(&model.ctx, &model.config, model.geometry).unwrap(),
275	            RecurrentState::new(&model.ctx, &model.config, model.geometry).unwrap(),
276	        ];
277	        let mut rec_refs: Vec<&mut RecurrentState> = rec_states.iter_mut().collect();
278	        let mut gs = model
279	            .create_batch_decode_graph_state(cache.pool().padding_block_id())
280	            .unwrap();
281	        let first_logits = if unified {
282	            model
283	                .unified_step(
284	                    &prompts,
285	                    &views,
286	                    &mut rec_refs,
287	                    &[],
288	                    &[],
289	                    cache.buffer(),
290	                    &mut gs,
291	                )
292	                .unwrap()
293	                .prefill_logits
294	                .unwrap()
295	        } else {
296	            model
297	                .batch_prefill_logits(&prompts, &views, &mut rec_refs, cache.buffer())
298	                .unwrap()
299	        };
300	        let first = greedy_sample_batch(model, &first_logits, 2);
301	        for (kv, token) in kvs.iter_mut().zip(&first) {
302	            cache.apply_prefill(kv, Some(*token)).unwrap();
303	        }
304	        gs.copy_state_to_slot(&model.ctx, &rec_states[0], 0)
305	            .unwrap();
306	        gs.copy_state_to_slot(&model.ctx, &rec_states[1], 1)
307	            .unwrap();
308	        let mut tokens_a = vec![first[0]];
309	        let mut tokens_b = vec![first[1]];
310	        for _ in 1..num_steps {
311	            for kv in &mut kvs {
312	                cache.schedule_decode(kv).unwrap();
313	            }
314	            let views = kvs
315	                .iter()
316	                .map(|kv| cache.decode_view(kv))
317	                .collect::<Vec<_>>();
318	            let tids = [*tokens_a.last().unwrap(), *tokens_b.last().unwrap()];
319	            if unified {
320	                model
321	                    .unified_step(&[], &[], &mut [], &tids, &views, cache.buffer(), &mut gs)
322	                    .unwrap();
323	            } else {
324	                model
325	                    .batch_decode_graph(
326	                        &tids,
327	                        &views,
328	                        cache.buffer(),
329	                        &mut gs,
330	                        DecodeGraphUse::Serve,
331	                    )
332	                    .unwrap();
333	            }
334	            let next = greedy_sample_batch(model, &gs.buffers.logits, 2);
335	            for (kv, token) in kvs.iter_mut().zip(&next) {
336	                cache.apply_decode(kv, *token).unwrap();
337	            }
338	            tokens_a.push(next[0]);
339	            tokens_b.push(next[1]);
340	        }
341	        (tokens_a, tokens_b)
342	    }
343	
344	    /// Verify that unified_step decode output matches batch_decode_graph standalone.
345	    #[test]
346	    fn unified_step_decode_matches_graph_decode() {
347	        let Some(model_path) =
348	            crate::test_fixture::model_path_or_skip("unified_step_decode_matches_graph_decode")
349	        else {
350	            return;
351	        };
352	        let model = Qwen35Model::from_safetensors(&model_path, 0, 2, 0).unwrap();
353	        let ref_tokens = run_decode_path(&model, false);
354	        let unified_tokens = run_decode_path(&model, true);
355	
356	        assert_eq!(
357	            unified_tokens, ref_tokens,
358	            "unified_step decode mismatch:\n  unified: {:?}\n  ref:     {:?}",
359	            unified_tokens, ref_tokens
360	        );
361	    }
362	}
