44	/// Current safe Qwen3.5 Shared-SM overlap admission cap.
45	///
46	/// Decode buckets above this value fall back to the prefill cuBLAS handle today.
47	/// Replaying decode while async prefill concurrently calls that same handle from
48	/// another stream relies on undocumented single-handle multi-stream behavior.
49	/// Keep overlap opt-in below this boundary until the larger decode buckets have
50	/// an independent per-stream handle/workspace route.
51	pub const MAX_SHARED_SM_DECODE_BATCH: usize = ops::GEMM_LT_MAX_N;
52	const _: () = assert!(MAX_SHARED_SM_DECODE_BATCH <= ops::GEMM_LT_MAX_N);
