119	    fn schedule_prefill_views(
120	        &self,
121	        kvs: &mut [Box<RequestKv>],
122	        windows: &[Vec<u32>],
123	    ) -> Result<Vec<KvView>> {
124	        debug_assert_eq!(kvs.len(), windows.len());
125	        for (scheduled, (kv, window)) in kvs.iter_mut().zip(windows).enumerate() {
126	            if let Err(error) = self.kv_cache.schedule_prefill(kv, window.len()) {
127	                self.kv_cache
128	                    .revert_scheduled_requests(kvs.iter_mut().take(scheduled).map(Box::as_mut));
129	                return Err(error);
130	            }
131	        }
132	        Ok(kvs
133	            .iter()
134	            .zip(windows)
135	            .map(|(kv, window)| self.kv_cache.prefill_view(kv, window.len()))
136	            .collect())
137	    }
