139	    fn schedule_decode_views(&self, active: &mut [ActiveRequest35]) -> Result<Vec<KvView>> {
140	        for (scheduled, request) in active.iter_mut().enumerate() {
141	            let ActiveBackendState::Single { kv, .. } = &mut request.backend_state else {
142	                panic!("single-GPU decode received TP active state")
143	            };
144	            if let Err(error) = self.kv_cache.schedule_decode(kv) {
145	                self.kv_cache.revert_scheduled_requests(
146	                    active
147	                        .iter_mut()
148	                        .take(scheduled)
149	                        .filter_map(active_request_kv),
150	                );
151	                return Err(error);
152	            }
153	        }
154	        Ok(active
155	            .iter()
156	            .map(|request| match &request.backend_state {
157	                ActiveBackendState::Single { kv, .. } => self.kv_cache.decode_view(kv),
158	                ActiveBackendState::Tp { .. } => {
159	                    panic!("single-GPU decode received TP active state")
160	                }
161	            })
162	            .collect())
163	    }
