165	    pub(super) fn apply_prefill(
166	        &mut self,
167	        chunk: &mut ScheduledChunk,
168	        tokens: &[u32],
169	    ) -> Result<()> {
170	        let ScheduledChunkBackendState::Single { kvs, recs } = &mut chunk.backend_state else {
171	            anyhow::bail!("single-GPU commit received TP chunk state")
172	        };
173	        for (i, (kv, rec)) in kvs.iter_mut().zip(recs.iter()).enumerate() {
174	            let is_final = chunk.ends[i] == chunk.reqs[i].request.prompt_tokens.len();
175	            let boundary = self
176	                .kv_cache
177	                .apply_prefill(kv, is_final.then_some(tokens[i]))?;
178	            anyhow::ensure!(
179	                rec.seq_len == boundary,
180	                "Qwen3.5 prefill apply position mismatch: kv={boundary}, recurrent={}",
181	                rec.seq_len
182	            );
183	            if let Some(reservation) = self.kv_cache.reserve_snapshot(kv, boundary)? {
184	                if let Err(error) = self.recurrent_store.save(
185	                    self.model.device_ctx(),
186	                    reservation.recurrent_slot(),
187	                    rec,
188	                ) {
189	                    self.kv_cache.abort_snapshot(reservation);
190	                    return Err(error);
191	                }
192	                self.kv_cache.publish_snapshot(reservation);
193	            }
194	        }
195	        Ok(())
196	    }
