198	    pub(super) fn apply_decode(
199	        &self,
200	        active: &mut [ActiveRequest35],
201	        tokens: &[u32],
202	    ) -> Result<()> {
203	        anyhow::ensure!(active.len() == tokens.len(), "decode apply row mismatch");
204	        for (req, &token) in active.iter_mut().zip(tokens) {
205	            let ActiveBackendState::Single { kv, .. } = &mut req.backend_state else {
206	                anyhow::bail!("single-GPU decode apply received TP state")
207	            };
208	            self.kv_cache.apply_decode(kv, token)?;
209	        }
210	        Ok(())
211	    }
