303	    pub(super) fn alloc_prefill_state(
304	        &mut self,
305	        req: &Request,
306	    ) -> Result<(PrefillBackendState, usize), AdmissionError> {
307	        let mut rec = self
308	            .alloc_recurrent()
309	            .map_err(AdmissionError::Recoverable)?;
310	        let (mut kv, restore) = self
311	            .kv_cache
312	            .begin_request(
313	                &req.prompt_tokens,
314	                req.max_tokens,
315	                req.lora_adapter.as_deref(),
316	                true,
317	            )
318	            .map_err(AdmissionError::Recoverable)?;
319	        let cached_tokens = if let Some(restore) = restore {
320	            if let Err(error) = self.recurrent_store.restore(
321	                self.model.device_ctx(),
322	                restore.recurrent_slot(),
323	                &mut rec,
324	            ) {
325	                let _ = self.kv_cache.release_request(&mut kv);
326	                return Err(AdmissionError::Recoverable(error));
327	            }
328	            match self.kv_cache.finish_restore(&kv, restore, &[rec.seq_len]) {
329	                Ok(tokens) => tokens,
330	                Err(error) => {
331	                    let _ = self.kv_cache.release_request(&mut kv);
332	                    return Err(AdmissionError::Recoverable(error));
333	                }
334	            }
335	        } else {
336	            0
337	        };
338	        Ok((
339	            PrefillBackendState::Single {
340	                kv: Box::new(kv),
341	                rec,
342	            },
343	            cached_tokens,
344	        ))
345	    }
