356	        let window_refs: Vec<&[u32]> = chunk.windows.iter().map(Vec::as_slice).collect();
357	        let ScheduledChunkBackendState::Single { kvs, recs } = &mut chunk.backend_state else {
358	            anyhow::bail!("single-GPU prefill received TP chunk state");
359	        };
360	        let views = self.schedule_prefill_views(kvs, &chunk.windows)?;
361	        let mut rec_refs: Vec<&mut RecurrentState> = recs.iter_mut().collect();
362	        let result = self.model.batch_prefill_logits(
363	            &window_refs,
364	            &views,
365	            &mut rec_refs,
366	            self.kv_cache.buffer(),
367	        );
368	        if result.is_err() {
369	            self.kv_cache
370	                .revert_scheduled_requests(kvs.iter_mut().map(Box::as_mut));
371	        }
