379	    pub(super) fn launch_async_prefill(
380	        &mut self,
381	        chunk: &mut ScheduledChunk,
382	    ) -> Result<AsyncPrefillOutput> {
383	        let prefill_stream = self
384	            .prefill_stream
385	            .clone()
386	            .ok_or_else(|| anyhow::anyhow!("Qwen3.5 decode overlap is disabled"))?;
387	
388	        // Request KV/recurrent state was allocated on the model stream. Order
389	        // those producers before the prefill stream without blocking the host.
390	        prefill_stream
391	            .join(&self.model.device_ctx().stream)
392	            .map_err(|err| anyhow::anyhow!("join Qwen3.5 prefill stream: {err}"))?;
393	
394	        let window_refs: Vec<&[u32]> = chunk.windows.iter().map(Vec::as_slice).collect();
395	        let ScheduledChunkBackendState::Single { kvs, recs } = &mut chunk.backend_state else {
396	            anyhow::bail!("single-GPU async prefill received TP chunk state");
397	        };
398	        let views = self.schedule_prefill_views(kvs, &chunk.windows)?;
399	        let mut rec_refs: Vec<&mut RecurrentState> = recs.iter_mut().collect();
400	        let logits = match self.model.batch_prefill_logits_on_stream(
401	            Arc::clone(&prefill_stream),
402	            &window_refs,
403	            &views,
404	            self.kv_cache.buffer(),
405	            &mut rec_refs,
406	        ) {
407	            Ok(logits) => logits,
408	            Err(err) => {
409	                if let Err(sync_err) = prefill_stream.synchronize() {
410	                    fatal_cuda_lifecycle(&format!(
411	                        "Qwen3.5 async prefill failed ({err}); stream drain failed: {sync_err}"
412	                    ));
413	                }
414	                self.kv_cache
415	                    .revert_scheduled_requests(kvs.iter_mut().map(Box::as_mut));
416	                return Err(err);
417	            }
418	        };
419	        let done = match prefill_stream.record_event(None) {
420	            Ok(done) => done,
421	            Err(err) => {
422	                if let Err(sync_err) = prefill_stream.synchronize() {
423	                    fatal_cuda_lifecycle(&format!(
424	                        "record Qwen3.5 async prefill event failed ({err}); stream drain failed: {sync_err}"
425	                    ));
426	                }
427	                return Err(anyhow::anyhow!("record Qwen3.5 async prefill event: {err}"));
428	            }
429	        };
430	        Ok(AsyncPrefillOutput {
431	            logits: Some(logits),
432	            done,
433	            stream: prefill_stream,
434	            completed: false,
435	        })
436	    }
