567	
568	        let ctx = self.model.device_ctx();
569	        let src = &self.graph_state.slot_states[compaction.moved_from];
570	        for layer_idx in 0..src.layers.len() {
571	            let (src_part, dst_part) = if compaction.moved_to < compaction.moved_from {
572	                let (left, right) = self
573	                    .graph_state
574	                    .slot_states
575	                    .split_at_mut(compaction.moved_from);
576	                (
577	                    &right[0].layers[layer_idx],
578	                    &mut left[compaction.moved_to].layers[layer_idx],
579	                )
580	            } else {
581	                unreachable!("idx < active.len() <= last");
582	            };
583	
584	            ctx.stream
585	                .memcpy_dtod(&src_part.state, &mut dst_part.state)
586	                .expect("compact slot state copy failed");
587	            ctx.stream
588	                .memcpy_dtod(&src_part.conv_state.data, &mut dst_part.conv_state.data)
589	                .expect("compact slot conv_state copy failed");
590	        }
591	        self.graph_state.slot_states[compaction.moved_to].seq_len =
592	            self.graph_state.slot_states[compaction.moved_from].seq_len;
593	
594	        match &mut active[compaction.moved_to].backend_state {
595	            ActiveBackendState::Single { graph_slot_idx, .. } => {
596	                *graph_slot_idx = compaction.moved_to;
597	            }
598	            ActiveBackendState::Tp { .. } => {
599	                panic!("single-GPU slot compaction received TP active state")
600	            }
601	        }
602	    }
603	}
