719	            decode: tp_decode_items(active)?,
720	            prefill_sample_seed,
721	            decode_sample_seed,
722	        };
723	        let result = self.executor.execute_unified(&plan)?;
724	        let prefill = align_prefill_results(chunk, &result.prefill).map_err(|err| {
725	            self.executor
726	                .poison_after_mutation("unified prefill artifacts", &err)
727	        })?;
728	        let decode = align_decode_results(active, &result.decode).map_err(|err| {
729	            self.executor
