735	    pub(super) fn drop_request(
736	        &mut self,
737	        request_id: RequestId,
738	        expectation: DropExpectation,
739	    ) -> Result<()> {
740	        self.executor
741	            .drop_request_with_compaction(request_id, expectation, None)
742	    }
743	
744	    /// Remove the TP request at `idx` via swap_remove and stash the resulting
745	    /// slot compaction for the paired `drop_active_state`. Mirrors
746	    /// `compact_single_slot`: after the swap, slots `0..active.len()` stay
747	    /// dense because the moved request's slot follows it.
748	    pub(super) fn take_active_request(
749	        &mut self,
750	        active: &mut Vec<ActiveRequest35>,
751	        idx: usize,
752	    ) -> ActiveRequest35 {
753	        let compaction = compaction_after_retire(active.len(), idx);
754	        let removed = active.swap_remove(idx);
755	
756	        self.pending_compaction = compaction.map(|compaction| {
757	            let moved = &mut active[idx];
758	            let ActiveBackendState::Tp {
759	                request_id,
760	                slot_idx,
761	            } = &mut moved.backend_state
762	            else {
763	                panic!("TP scheduler received single-GPU active state")
764	            };
765	            debug_assert_eq!(*slot_idx, compaction.moved_from);
766	            *slot_idx = compaction.moved_to;
767	            TpSlotCompaction {
768	                moved_request_id: *request_id,
769	                from: compaction.moved_from,
770	                to: compaction.moved_to,
771	            }
772	        });
773	        removed
774	    }
775	}
