56	pub(super) fn launch_overlap_step(
57	    backend: &mut SchedulerBackend,
58	    active: &mut Vec<ActiveRequest35>,
59	    scheduled: Vec<PrefillingRequest35>,
60	    inflight_prefill: &mut Option<InflightPrefill>,
61	    rng: &mut StdRng,
62	    ledger: &mut RequestLedger,
63	) -> Result<()> {
64	    debug_assert!(inflight_prefill.is_none());
65	    let mut chunk = ScheduledChunk::from(scheduled);
66	    let decode_seed = rand::RngExt::random(rng);
67	    let prefill_seed = rand::RngExt::random(rng);
68	    let output = match backend {
69	        SchedulerBackend::Single(single) => single.launch_async_prefill(&mut chunk),
70	        SchedulerBackend::Tp(_) => unreachable!("Qwen3.5 TP cannot launch async prefill"),
71	    };
72	    match output {
73	        Ok(output) => {
74	            *inflight_prefill = Some(InflightPrefill {
75	                chunk,
76	                output,
77	                sample_seed: prefill_seed,
78	            });
79	        }
80	        Err(err) => {
81	            warn!("async prefill launch failed: {err}");
82	            fail_chunk(chunk, &err.to_string(), ledger);
83	        }
84	    }
85	    decode_step_with_seed(backend, active, decode_seed, ledger)
86	}
