88	pub(super) fn finish_async_prefill(
89	    backend: &mut SchedulerBackend,
90	    active: &mut Vec<ActiveRequest35>,
91	    prefilling: &mut Vec<PrefillingRequest35>,
92	    inflight: InflightPrefill,
93	    ledger: &mut RequestLedger,
94	) -> Result<()> {
95	    let InflightPrefill {
96	        mut chunk,
97	        output,
98	        sample_seed,
99	    } = inflight;
100	    let logits = output.into_logits();
101	    let SchedulerBackend::Single(single) = backend else {
102	        unreachable!("Qwen3.5 TP cannot finish async prefill");
103	    };
104	    let (tokens, logprobs) = match single.sample_prefill_logits(&chunk.reqs, &logits, sample_seed) {
105	        Ok(result) => result,
106	        Err(err) => {
107	            warn!("async prefill sampling failed: {err}");
108	            fail_chunk(chunk, &err.to_string(), ledger);
109	            return Ok(());
110	        }
111	    };
112	    single.apply_prefill(&mut chunk, &tokens)?;
113	    let artifacts = PrefillStepArtifacts::Single { tokens, logprobs };
114	    promote_or_requeue(single, active, prefilling, chunk, &artifacts, ledger)
115	}
