117	// ── Unified step (prefill chunk + decode in one forward pass) ──────────────
118	
119	pub(super) fn unified_step_sched(
120	    backend: &mut SchedulerBackend,
121	    active: &mut Vec<ActiveRequest35>,
122	    scheduled: Vec<PrefillingRequest35>,
123	    prefilling: &mut Vec<PrefillingRequest35>,
124	    rng: &mut StdRng,
125	    ledger: &mut RequestLedger,
126	) -> Result<()> {
127	    let mut chunk = ScheduledChunk::from(scheduled);
128	    if matches!(backend, SchedulerBackend::Tp(_)) {
129	        // Preserve the established scheduler RNG order: decode seed first,
130	        // prefill seed second. Workers execute the forwards in the opposite
131	        // (prefill-then-decode) order using these preselected seeds.
132	        let decode_sample_seed = rand::RngExt::random(rng);
133	        let prefill_sample_seed = rand::RngExt::random(rng);
134	        let result = {
135	            let SchedulerBackend::Tp(tp) = backend else {
136	                unreachable!()
137	            };
138	            tp.execute_unified(&chunk, active, decode_sample_seed, prefill_sample_seed)
139	        };
140	        let artifacts = match result {
141	            Ok(artifacts) => artifacts,
142	            Err(err) => {
143	                warn!("TP unified step failed: {err}");
144	                return Err(err);
145	            }
146	        };
147	
148	        let (decode_tokens, decode_logprobs) = split_decode_artifacts(&artifacts.decode);
149	        dispatch_decode_tokens(backend, active, &decode_tokens, &decode_logprobs, ledger)?;
150	
151	        let prefill = PrefillStepArtifacts::Tp(artifacts.prefill);
152	        return promote_or_requeue(backend, active, prefilling, chunk, &prefill, ledger);
153	    }
154	
155	    let SchedulerBackend::Single(backend) = backend else {
156	        unreachable!()
157	    };
158	    // Scope the borrows of `chunk` / `active` to the executor call so the error
159	    // and decode-processing paths can use them afterwards.
160	    let result = backend.unified_step(&mut chunk, active);
161	    let output = match result {
162	        Ok(v) => v,
163	        Err(e) => {
164	            warn!("unified step failed: {e}");
165	            let message = e.to_string();
166	            fail_active(active, &message, ledger);
167	            fail_chunk(chunk, &message, ledger);
168	            return Ok(());
169	        }
170	    };
171	    let decode_seed = rand::RngExt::random(rng);
172	    let prefill_seed = rand::RngExt::random(rng);
173	
174	    // Process decode results FIRST (it may retire requests and free graph slots
175	    // that promotion then fills densely).
176	    if output.decoded {
177	        process_decode_logits(backend, active, decode_seed, ledger)?;
178	    }
179	
180	    let prefill_logits = output
181	        .prefill_logits
182	        .as_ref()
183	        .expect("scheduled prefill chunk must return prefill logits");
184	    let (tokens, logprobs) =
185	        match backend.sample_prefill_logits(&chunk.reqs, prefill_logits, prefill_seed) {
186	            Ok(v) => v,
187	            Err(e) => {
188	                warn!("unified prefill sampling failed: {e}");
189	                fail_chunk(chunk, &e.to_string(), ledger);
190	                return Ok(());
191	            }
192	        };
193	    backend.apply_prefill(&mut chunk, &tokens)?;
194	    let prefill = PrefillStepArtifacts::Single { tokens, logprobs };
195	    promote_or_requeue(backend, active, prefilling, chunk, &prefill, ledger)
196	}
