198	// ── Decode step (pure decode, CUDA Graph enabled) ──────────────────────
199	
200	pub(super) fn decode_step(
201	    backend: &mut SchedulerBackend,
202	    active: &mut Vec<ActiveRequest35>,
203	    rng: &mut StdRng,
204	    ledger: &mut RequestLedger,
205	) -> Result<()> {
206	    // Preserve the historical scheduler RNG sequence: TP consumes the first
207	    // seed, while single-GPU decode consumed a second seed inside sampling.
208	    let first_seed = rand::RngExt::random(rng);
209	    let sample_seed = if matches!(backend, SchedulerBackend::Single(_)) {
210	        rand::RngExt::random(rng)
211	    } else {
212	        first_seed
213	    };
214	    decode_step_with_seed(backend, active, sample_seed, ledger)
215	}
216	
217	fn decode_step_with_seed(
218	    backend: &mut SchedulerBackend,
219	    active: &mut Vec<ActiveRequest35>,
220	    sample_seed: u64,
221	    ledger: &mut RequestLedger,
222	) -> Result<()> {
223	    let (tokens, logprobs_vec) = match backend {
224	        SchedulerBackend::Single(single) => {
225	            if let Err(e) = single.decode_graph(active) {
226	                warn!("batch_decode_graph error: {e}");
227	                let message = e.to_string();
228	                fail_active(active, &message, ledger);
229	                return Ok(());
230	            }
231	            // Snapshot logits to CPU BEFORE sampling (sampling may modify bufs.logits)
232	            match single.sample_decode_logits(active, sample_seed) {
233	                Ok(v) => v,
234	                Err(e) => {
235	                    warn!("decode sampling/logprobs error: {e}");
236	                    let message = e.to_string();
237	                    fail_active(active, &message, ledger);
238	                    return Ok(());
239	                }
240	            }
241	        }
242	        SchedulerBackend::Tp(tp) => match tp.execute_decode(active, sample_seed) {
243	            Ok(v) => split_decode_artifacts(&v),
244	            Err(e) => {
245	                warn!("TP eager decode error: {e}");
246	                return Err(e);
247	            }
248	        },
249	    };
250	
251	    if let SchedulerBackend::Single(single) = backend {
252	        single.apply_decode(active, &tokens)?;
253	    }
254	    dispatch_decode_tokens(backend, active, &tokens, &logprobs_vec, ledger)
255	}
