257	/// Process decode logits from unified step: sample, extract logprobs, dispatch.
258	fn process_decode_logits(
259	    backend: &mut SingleGpuBackend,
260	    active: &mut Vec<ActiveRequest35>,
261	    sample_seed: u64,
262	    ledger: &mut RequestLedger,
263	) -> Result<()> {
264	    let (tokens, logprobs_vec) = match backend.sample_decode_logits(active, sample_seed) {
265	        Ok(v) => v,
266	        Err(e) => {
267	            warn!("decode sampling/logprobs error: {e}");
268	            let message = e.to_string();
269	            fail_active(active, &message, ledger);
270	            return Ok(());
271	        }
272	    };
273	
274	    backend.apply_decode(active, &tokens)?;
275	    dispatch_decode_tokens(backend, active, &tokens, &logprobs_vec, ledger)
276	}
