278	/// Dispatch sampled decode tokens and retire completed backend state.
279	///
280	/// `tokens` and `logprobs` are indexed by original position in `active`.
281	/// Retirements collected first, then compacted in reverse order.
282	pub(super) fn dispatch_decode_tokens(
283	    backend: &mut impl DecodeDispatchBackend,
284	    active: &mut Vec<ActiveRequest35>,
285	    tokens: &[u32],
286	    logprobs: &[Option<TokenLogprob>],
287	    ledger: &mut RequestLedger,
288	) -> Result<()> {
289	    let mut to_retire = Vec::new();
290	    for (i, req) in active.iter_mut().enumerate() {
291	        if ledger.is_aborted(req.id) {
292	            to_retire.push((i, None));
293	            continue;
294	        }
295	        let token = tokens[i];
296	        let finish = if let Some(cause) = req
297	            .stop_policy
298	            .classify(token, |id| backend.is_stop_token(id))
299	        {
300	            Some((FinishReason::Stop, Some(cause)))
301	        } else if ledger.completion_tokens(req.id) + 1 >= req.max_tokens {
302	            Some((FinishReason::Length, None))
303	        } else {
304	            None
305	        };
306	        if finish.is_some() {
307	            to_retire.push((i, finish));
308	        } else {
309	            ledger.push_tokens(req.id, &[token], std::slice::from_ref(&logprobs[i]));
310	            req.last_token = token;
311	        }
312	    }
313	
314	    // Keep slots dense and wait for retirement ACK before publishing completion.
315	    for (i, finish) in to_retire.into_iter().rev() {
316	        let request = backend.take_active_request(active, i);
317	        backend.drop_active_state(&request.backend_state)?;
318	        if ledger.is_aborted(request.id) {
319	            ledger.retire(request.id);
320	        } else if let Some((reason, stop_cause)) = finish {
321	            ledger.push_tokens(request.id, &[tokens[i]], std::slice::from_ref(&logprobs[i]));
322	            debug!(
323	                "request finished: request_id={:?} prompt_tokens={} completion_tokens={} finish_reason={:?}",
324	                request.client_label,
325	                request.prompt_len,
326	                ledger.completion_tokens(request.id),
327	                reason
328	            );
329	            ledger.finish_with_cause(request.id, reason, stop_cause);
330	        }
331	    }
332	    Ok(())
333	}
