371	        idx: usize,
372	    ) -> ActiveRequest35 {
373	        match self {
374	            SchedulerBackend::Single(backend) => compact_single_slot(backend, active, idx),
375	            SchedulerBackend::Tp(backend) => backend.take_active_request(active, idx),
376	        }
