379	    fn drop_active_state(&mut self, state: &ActiveBackendState) -> Result<()> {
380	        match (self, state) {
381	            (SchedulerBackend::Single(_), ActiveBackendState::Single { .. }) => Ok(()),
382	            (SchedulerBackend::Tp(backend), ActiveBackendState::Tp { request_id, .. }) => {
383	                let compaction = backend.pending_compaction.take();
384	                backend.executor.drop_request_with_compaction(
385	                    *request_id,
386	                    DropExpectation::MustExist,
387	                    compaction,
388	                )
389	            }
390	            _ => anyhow::bail!("mismatched Qwen3.5 scheduler backend state during retirement"),
391	        }
392	    }
