395	/// Remove single-GPU request at `idx` via swap_remove and compact graph slots.
396	///
397	/// After swap_remove, the element that was at `active.len()-1` (before remove)
398	/// now sits at `idx`. Its graph slot must be copied into the vacated slot so
399	/// that slots 0..active.len() remain dense.
400	fn compact_single_slot(
401	    backend: &mut SingleGpuBackend,
402	    active: &mut Vec<ActiveRequest35>,
403	    idx: usize,
404	) -> ActiveRequest35 {
405	    let compaction = compaction_after_retire(active.len(), idx);
406	    let removed = active.swap_remove(idx);
407	
408	    if let Some(compaction) = compaction {
409	        backend.compact_slot(active, compaction);
410	    }
411	    removed
412	}
