445	
446	impl From<Vec<PrefillingRequest35>> for ScheduledChunk {
447	    fn from(scheduled: Vec<PrefillingRequest35>) -> Self {
448	        let n = scheduled.len();
449	        let is_tp = scheduled
450	            .first()
451	            .is_some_and(|p| matches!(p.backend_state, PrefillBackendState::Tp { .. }));
452	        let mut chunk = ScheduledChunk {
453	            reqs: Vec::with_capacity(n),
454	            backend_state: if is_tp {
455	                ScheduledChunkBackendState::Tp {
456	                    request_ids: Vec::with_capacity(n),
457	                }
458	            } else {
459	                ScheduledChunkBackendState::Single {
460	                    kvs: Vec::with_capacity(n),
461	                    recs: Vec::with_capacity(n),
462	                }
463	            },
464	            ends: Vec::with_capacity(n),
465	            windows: Vec::with_capacity(n),
466	        };
467	        for p in scheduled {
468	            let end = p.cursor + p.step_chunk;
469	            chunk
470	                .windows
471	                .push(p.req.request.prompt_tokens[p.cursor..end].to_vec());
472	            chunk.ends.push(end);
473	            chunk.reqs.push(p.req);
474	            match (&mut chunk.backend_state, p.backend_state) {
475	                (
476	                    ScheduledChunkBackendState::Single { kvs, recs },
477	                    PrefillBackendState::Single { kv, rec },
478	                ) => {
479	                    kvs.push(kv);
480	                    recs.push(rec);
481	                }
482	                (
483	                    ScheduledChunkBackendState::Tp { request_ids },
484	                    PrefillBackendState::Tp { request_id },
485	                ) => request_ids.push(request_id),
486	                _ => unreachable!("mixed Qwen3.5 scheduler backend states in one chunk"),
487	            }
488	        }
489	        chunk
490	    }
491	}
492	
493	/// Pull this step's prefill set off the FRONT of `prefilling`, capping the
494	/// step's total forwarded prompt tokens at `prefill_budget`.
495	pub(super) fn take_prefill_chunks(
496	    prefilling: &mut Vec<PrefillingRequest35>,
497	    prefill_budget: usize,
498	    snapshot_stride: Option<usize>,
499	) -> Vec<PrefillingRequest35> {
500	    let remaining: Vec<usize> = prefilling
501	        .iter()
502	        .map(|p| p.req.request.prompt_tokens.len() - p.cursor)
503	        .collect();
504	    let chunks = plan_prefill_chunks(&remaining, prefill_budget);
505	    let mut scheduled: Vec<PrefillingRequest35> = prefilling.drain(0..chunks.len()).collect();
506	    for (p, chunk) in scheduled.iter_mut().zip(&chunks) {
507	        p.step_chunk = clamp_prefill_chunk(p.cursor, *chunk, snapshot_stride);
508	    }
509	    scheduled
510	}
511	
512	/// Report a forward/sampling failure to every request in the failed chunk.
513	fn fail_chunk(chunk: ScheduledChunk, message: &str, ledger: &mut RequestLedger) {
514	    for req in chunk.reqs {
515	        fail_or_retire(req.id, message, ledger);
516	    }
517	}
518	
519	fn fail_active(active: &mut Vec<ActiveRequest35>, message: &str, ledger: &mut RequestLedger) {
520	    for req in active.drain(..) {
521	        fail_or_retire(req.id, message, ledger);
522	    }
523	}
524	
525	/// Commit immediate completions after retirement, and put unfinished chunks
526	/// back at the front of the prefill queue without changing their FIFO order.
527	pub(super) fn promote_or_requeue(
528	    backend: &mut impl PrefillPromoteBackend,
529	    active: &mut Vec<ActiveRequest35>,
530	    prefilling: &mut Vec<PrefillingRequest35>,
531	    chunk: ScheduledChunk,
532	    artifacts: &PrefillStepArtifacts,
533	    ledger: &mut RequestLedger,
534	) -> Result<()> {
535	    let ScheduledChunk {
536	        reqs,
537	        backend_state,
538	        ends,
539	        ..
540	    } = chunk;
541	    let mut still_prefilling = Vec::new();
542	    let backend_states = split_scheduled_backend_state(backend_state);
543	    for (i, ((req, backend_state), end)) in
544	        reqs.into_iter().zip(backend_states).zip(ends).enumerate()
545	    {
546	        if ledger.is_aborted(req.id) {
547	            backend.drop_prefill_state(&backend_state, DropExpectation::MustExist)?;
548	            ledger.retire(req.id);
549	            continue;
550	        }
551	        if end < req.request.prompt_tokens.len() {
552	            still_prefilling.push(PrefillingRequest35 {
553	                req,
554	                backend_state,
555	                cursor: end,
556	                step_chunk: 0,
557	            });
558	            continue;
559	        }
560	
561	        let artifact = artifacts.final_artifact(i);
562	        let first_token = artifact.token;
563	        let finish = if let Some(cause) = req
564	            .request
565	            .stop_policy
566	            .classify(first_token, |id| backend.is_stop_token(id))
567	        {
568	            Some((FinishReason::Stop, Some(cause)))
569	        } else if req.request.max_tokens <= 1 {
570	            Some((FinishReason::Length, None))
571	        } else {
572	            None
573	        };
574	        if let Some((reason, stop_cause)) = finish {
575	            backend.drop_prefill_state(&backend_state, DropExpectation::MustExist)?;
576	            if ledger.is_aborted(req.id) {
577	                ledger.retire(req.id);
578	            } else {
579	                ledger.push_tokens(req.id, &[first_token], &[artifact.logprob]);
580	                ledger.finish_with_cause(req.id, reason, stop_cause);
581	            }
582	            continue;
583	        }
584	
585	        let active_backend_state = backend.promote_prefill_state(active.len(), backend_state);
586	        ledger.push_tokens(req.id, &[first_token], &[artifact.logprob]);
587	        active.push(ActiveRequest35 {
588	            id: req.id,
589	            client_label: req.request.client_label,
590	            backend_state: active_backend_state,
591	            last_token: first_token,
592	            max_tokens: req.request.max_tokens,
593	            prompt_len: req.request.prompt_tokens.len(),
594	            params: req.request.params,
595	            stop_policy: req.request.stop_policy,
596	            logprobs: req.request.logprobs,
597	        });
598	    }
599	    prefilling.splice(0..0, still_prefilling);
600	    Ok(())
601	}
602	
603	pub(super) trait PrefillPromoteBackend {
604	    fn is_stop_token(&self, token: u32) -> bool;
605	    fn promote_prefill_state(
606	        &mut self,
607	        active_len: usize,
608	        state: PrefillBackendState,
609	    ) -> ActiveBackendState;
610	    fn drop_prefill_state(
611	        &mut self,
612	        state: &PrefillBackendState,
613	        expectation: DropExpectation,
614	    ) -> Result<()>;
615	}
616	
617	impl PrefillPromoteBackend for SingleGpuBackend {
618	    fn is_stop_token(&self, token: u32) -> bool {
619	        self.is_stop_token(token)
620	    }
621	
622	    fn promote_prefill_state(
623	        &mut self,
624	        active_len: usize,
625	        state: PrefillBackendState,
626	    ) -> ActiveBackendState {
627	        let PrefillBackendState::Single { kv, rec } = state else {
628	            panic!("single-GPU promotion received TP prefill state");
629	        };
630	        let slot_idx = slot_for_new_request(active_len, self.max_batch())
631	            .expect("admission must reserve a graph slot");
632	        self.copy_recurrent_to_slot(&rec, slot_idx)
633	            .expect("copy recurrent state to slot failed");
634	        ActiveBackendState::Single {
635	            kv,
636	            graph_slot_idx: slot_idx,
637	        }
638	    }
639	
640	    fn drop_prefill_state(
641	        &mut self,
642	        _state: &PrefillBackendState,
643	        _expectation: DropExpectation,
644	    ) -> Result<()> {
645	        Ok(())
646	    }
647	}
648	
649	impl PrefillPromoteBackend for SchedulerBackend {
650	    fn is_stop_token(&self, token: u32) -> bool {
651	        self.is_stop_token(token)
652	    }
653	
654	    fn promote_prefill_state(
655	        &mut self,
656	        active_len: usize,
657	        state: PrefillBackendState,
658	    ) -> ActiveBackendState {
659	        match (self, state) {
660	            (SchedulerBackend::Single(single), state @ PrefillBackendState::Single { .. }) => {
661	                single.promote_prefill_state(active_len, state)
662	            }
663	            (SchedulerBackend::Tp(backend), PrefillBackendState::Tp { request_id }) => {
664	                let slot_idx = slot_for_new_request(active_len, backend.max_batch())
665	                    .expect("admission must reserve a TP decode slot");
666	                ActiveBackendState::Tp {
667	                    request_id,
668	                    slot_idx,
669	                }
670	            }
671	            _ => panic!("mismatched Qwen3.5 scheduler backend state during promotion"),
672	        }
673	    }
674	
675	    fn drop_prefill_state(
676	        &mut self,
677	        state: &PrefillBackendState,
678	        expectation: DropExpectation,
679	    ) -> Result<()> {
680	        match (self, state) {
681	            (SchedulerBackend::Single(_), PrefillBackendState::Single { .. }) => Ok(()),
682	            (SchedulerBackend::Tp(backend), PrefillBackendState::Tp { request_id }) => {
683	                backend.drop_request(*request_id, expectation)
684	            }
685	            _ => anyhow::bail!("mismatched Qwen3.5 scheduler backend state during prefill drop"),
686	        }
687	    }
688	}
689	
690	fn split_scheduled_backend_state(
691	    backend_state: ScheduledChunkBackendState,
692	) -> Vec<PrefillBackendState> {
693	    match backend_state {
694	        ScheduledChunkBackendState::Single { kvs, recs } => kvs
695	            .into_iter()
696	            .zip(recs)
697	            .map(|(kv, rec)| PrefillBackendState::Single { kv, rec })
698	            .collect(),
699	        ScheduledChunkBackendState::Tp { request_ids } => request_ids
700	            .into_iter()
701	            .map(|request_id| PrefillBackendState::Tp { request_id })
702	            .collect(),
703	    }
704	}
