206	    model: Qwen35Model,
207	    seed: u64,
208	    max_batch: usize,
209	    max_prefill_tokens: usize,
210	    scheduler_policy: Qwen35SchedulerPolicy,
211	    decode_overlap: Qwen35DecodeOverlap,
212	) -> Result<Engine> {
213	    assert!(
214	        max_prefill_tokens > 0,
215	        "max_prefill_tokens must be positive: a zero budget can never schedule a prefill chunk"
216	    );
217	    // Static instance cap for the vLLM bridge's max_model_len. Live admission
218	    // still uses the current page budget inside the scheduler loop.
219	    let backend = SingleGpuBackend::new(model, max_batch, decode_overlap)?;
220	    let total_blocks = backend.capacity_pages_for_requests();
221	    let block_size = backend.page_size();
222	    let servable = servable_len(
223	        backend.model().config().max_position_embeddings,
224	        total_blocks,
